script:
frappe.ui.form.on('Stock Entry', {
	setup: function(frm){
	    frm.set_query('batch_no', 'items', function(doc, cdt, cdn) {
			var item = locals[cdt][cdn];
			if(!item.item_code) {
				frappe.throw(__("Please enter Item Code to get Batch Number"));
			} else {
				if (in_list(["Material Transfer for Manufacture", "Manufacture", "Repack", "Send to Subcontractor"], doc.purpose)) {
					var filters = {
						'item_code': item.item_code,
						'posting_date': ['<=', frm.doc.posting_date]
					}
				} else {
					var filters = {
						'item_code': item.item_code
					}
				}


				return {
					query : "erpnext.controllers.queries.get_batch_no",
					filters: filters
				}
			}
		});

        frm.set_query('batch', () => {
			return {
				filters: {
					workflow_state: 'Approved'
				}
			}
		});


	}
})

frappe.ui.form.on('Job Card', {
    onload:function(frm){
	    var products_list;
	    frappe.call({
	        type: 'GET',
	        url: '/api/method/get_items_under_products',
	        async: false,
	        callback: function(r){
	            products_list = r.message;
	        }
	    })
        frm.set_query('batch_no', () => {
			return {
				filters: {
					item: ['in', products_list],
					workflow_state: 'Approved'
				}
			}
		});
    },

	start_job: function(frm) {
		let row = frappe.model.add_child(frm.doc, 'Job Card Time Log', 'time_logs');
		frappe.db.get_value("Employee",frm.doc.employee,"employee_name",(c)=>{
		row.employee=c.employee_name;
		row.completed_qty = 0;
		})
		row.from_time = frappe.datetime.now_datetime();
		frm.set_value('job_started', 1);
		frm.set_value('started_time' , row.from_time);
		frm.set_value("status", "Work In Progress");

		if (!frappe.flags.resume_job) {
			frm.set_value('current_time' , 0);
		}
		frm.save();
	}
});

frappe.ui.form.on('Job Card Time Log', {
	pcs_completed: function(frm, cdt, cdn){
	    var row = locals[cdt][cdn];
	    if(row.pcs_completed != undefined){
	        var completed_qty = row.pcs_completed / 12;
	        frappe.model.set_value(cdt, cdn, "completed_qty", completed_qty);
	    }
	    frm.refresh_field('completed_qty');
	}
})

frappe.ui.form.on('Batch', {
	item: function(frm) {
	    fetch_mrp(frm);
	},

	manufacturing_date: function(frm){
	    fetch_mrp(frm);
	}
})

function fetch_mrp(frm){
    if(frm.doc.item != undefined){
        frappe.db.get_value("Item Price", {'item_code': frm.doc.item, 'selling': 1, 'valid_from': ['<', frm.doc.manufacturing_date], 'valid_upto': ['>=', frm.doc.manufacturing_date]}, "price_list_rate",(c)=>{
		    if(c.price_list_rate != undefined){
    		    frm.set_value('mrp', c.price_list_rate);
		        frm.refresh_field('mrp');
		    }else{
		        frm.set_value('mrp', 0);
		        frm.refresh_field('mrp');
		    }
	    })
    }
}

frappe.ui.form.on('Work Order', {
	onload:function(frm){
	    var products_list;
	    frappe.call({
	        type: 'GET',
	        url: '/api/method/get_items_under_products',
	        async: false,
	        callback: function(r){
	            products_list = r.message;
	        }
	    })
        frm.set_query('batch_no', () => {
			return {
				filters: {
					item: ['in', products_list],
					workflow_state: 'Approved'
				}
			}
		});
    }
})

frappe.ui.form.on('Delivery Note', {
	onload: function(frm) {
		frm.set_query('batch_no', 'items', function(doc, cdt, cdn) {
			var item = locals[cdt][cdn];
			if(!item.item_code) {
				frappe.throw(__("Please enter Item Code to get Batch Number"));
			} else {
				var filters = {
						'item_code': item.item_code
					}
				return {
					query : "erpnext.controllers.queries.get_batch_no",
					filters: filters
				}
			}
		});
	}
})

frappe.ui.form.on('Delivery Note Item', {
	batch_no: function(frm, cdt, cdn) {
	    var row = locals[cdt][cdn];
		if(row.batch_no != undefined){
            frappe.db.get_value("Batch", {'name': row.batch_no}, "mrp",(c)=>{
    		    if(c.mrp != undefined){
        		    frappe.model.set_value(cdt, cdn, 'rate', c.mrp);
    		        frm.refresh_field('rate');
    		    }
    	    })
        }
	}
})
